#!/usr/bin/env python3
"""Inline the tested diagnostic pages into the book, in code order."""
import argparse
from pathlib import Path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="reject a stale index")
    args = parser.parse_args()
    root = Path(__file__).resolve().parent.parent
    parts = [
        "# Error index\n\n",
        "<!-- Generated by tools/gen-error-index.py. Edit crates/evocc/explain/*.md. -->\n\n",
        "Each example is checked by the explanation-page tests.\n",
        "A runtime example describes an executed path, not all possible inputs.\n",
        "`Trigger: none` states why a code has no C trigger in this profile.\n\n",
    ]
    group = None
    for page in sorted((root / "crates/evocc/explain").glob("*.md")):
        if page.stem[:2] != group:
            group = page.stem[:2]
            parts.append(f"## {group}xxx\n\n")
        text = page.read_text(encoding="utf-8").replace("# ", "### ", 1)
        # The test tags identify examples; mdBook only needs the C language tag.
        lines = ["```c" if line.startswith("```c,") else line for line in text.splitlines()]
        parts.append("\n".join(lines) + "\n\n")
    expected = "".join(parts)
    output = root / "book/src/error-index.md"
    if args.check:
        if not output.is_file() or output.read_text(encoding="utf-8") != expected:
            raise SystemExit("error index is stale; run python3 tools/gen-error-index.py")
    else:
        output.write_text(expected, encoding="utf-8")


if __name__ == "__main__":
    main()
